from urllib.parse import urlparse

class UrlClassifier:
    def __init__(self):
        self.categories = {}

    def train(self, urls, categories):
        """Train the classifier on a set of categorized URLs."""
        for url, category in zip(urls, categories):
            parsed = urlparse(url)
            base_url = parsed.scheme + "://" + parsed.netloc
            self.categories[base_url] = category

    def classify(self, url):
        """Classify a URL using the trained categories."""
        for trained_url, category in self.categories.items():
            if url.startswith(trained_url):
                return category

        domain = urlparse(url).netloc
        return domain

def main():
    classifier = UrlClassifier()

    classifier.train(["http://example.com",
                      "http://google.com",
                      "http://nasa.gov"],
                     ["Example",
                      "Search Engine",
                      "Government"])

    for url in ["http://wikipedia.org",
                "http://example.com/page",
                "http://microsoft.com"]:
        print(classifier.classify(url))

if __name__ == "__main__":
    main()

