import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse

urls = set()

def crawl(url):
    try:
        html = requests.get(url).text
        soup = BeautifulSoup(html, 'html.parser')

        links = soup.find_all('a')
        for link in links:
            href = link.get('href')
            if href:
                o = urlparse(href)
                if o.netloc == start_url.netloc:
                    urls.add(href)
    except:
        pass

def get_sitemap(start_url):
    crawl(start_url)
    return list(urls)

