import os
import zipfile

def compress_logs(logs_dir, zip_file):
    os.chmod(zip_file, 0o600)

    with zipfile.ZipFile(zip_file, 'w') as z:
        for dirpath, _, filenames in os.walk(logs_dir):
            for f in filenames:
                if f.endswith('.log'):
                    file_path = os.path.join(dirpath, f)
                    z.write(file_path, arcname=f)

compress_logs('/var/log/nginx', '/tmp/nginx_logs.zip')

